<script setup lang="ts">
import { Settings2, Sun, Moon, Monitor, PenLine, Database, Download, Upload, Check, RefreshCw, ArrowUpRight } from 'lucide-vue-next'
import type { SiteSettings, ThemePreference } from '#shared/workspace'
import type { ImportPlan } from '#shared/workspace'
const route = useRoute(); const router = useRouter()
const { data: workspace, refresh } = await useAdminWorkspace()
const { data: dataInfo, refresh: refreshData } = await useAdminData<{ content: number; bases: number; terms: number; assets: number; operations: { action: string; detail: string; success: boolean; at: string }[] } | null>('/api/admin/data', null)
const tab = computed(() => ['general','appearance','editor','data'].includes(String(route.query.tab)) ? String(route.query.tab) : 'general')
const form = ref<SiteSettings | null>(null); const dirty = ref(false); const busy = ref(false); const message = ref('')
const { selection, setTheme, resetTheme } = useTheme()
const choices: { id: ThemePreference; name: string; icon: typeof Sun; caption: string }[] = [{ id: 'light', name: '浅色', icon: Sun, caption: '白底与深色文字' }, { id: 'dark', name: '深色', icon: Moon, caption: '深灰底与柔和文字' }, { id: 'system', name: '跟随系统', icon: Monitor, caption: '自动匹配设备外观' }]
watch(workspace, value => { if (value && !dirty.value) form.value = structuredClone(toRaw(value.settings)) }, { immediate: true })
const types = computed(() => workspace.value?.terms.filter(t => t.kind === 'type' && t.enabled) || [])
function changeTab(id: string) { if (dirty.value && id === 'data') { message.value = '请先保存或撤销设置，再进入数据管理'; return }; message.value = ''; void router.replace({ query: { tab: id } }) }
async function save() {
  if (!form.value || !workspace.value) return
  busy.value = true; message.value = ''
  try { const result = await $fetch('/api/admin/settings', { method: 'POST', body: { revision: workspace.value.revision, settings: form.value } }); dirty.value = false; workspace.value = result; form.value = structuredClone(result.settings); await refreshNuxtData('site-workspace'); message.value = '设置已保存' }
  catch (e: any) { message.value = e.data?.statusMessage || '保存失败'; if (e.status === 409) await refresh() }
  finally { busy.value = false }
}
const fileInput = ref<HTMLInputElement>(); const files = ref<File[]>([]); const plan = ref<ImportPlan | null>(null); const restoreSettings = ref(false); const importAt = ref(''); const importing = ref(false)
function fileChanged(event: Event) { files.value = [...((event.target as HTMLInputElement).files || [])]; plan.value = null; importAt.value = new Date().toISOString(); message.value = '' }
watch(restoreSettings, () => { plan.value = null })
async function runImport(action: 'plan' | 'apply') {
  if (!files.value.length) return
  importing.value = true; message.value = ''
  const data = new FormData(); for (const file of files.value) data.append('file', file)
  data.append('action', action); data.append('restoreSettings', String(restoreSettings.value)); data.append('importedAt', importAt.value)
  if (plan.value) data.append('token', plan.value.token)
  try {
    const result = await $fetch<{ plan?: ImportPlan; result?: { imported: number; skipped: number; knowledge: number } }, string>('/api/admin/import', { method: 'POST', body: data })
    if (result.plan) plan.value = result.plan
    else if (result.result) { message.value = `导入完成：新增 ${result.result.imported} 项，跳过 ${result.result.skipped} 项，恢复 ${result.result.knowledge} 个知识库。`; plan.value = null; files.value = []; if (fileInput.value) fileInput.value.value = ''; dirty.value = false; await refresh(); await refreshData(); await refreshNuxtData('site-workspace') }
  } catch (e: any) { message.value = e.data?.statusMessage || '导入失败，未完成写入'; if (action === 'apply') plan.value = null; await refreshData() }
  finally { importing.value = false }
}
function discard() { if (workspace.value) form.value = structuredClone(toRaw(workspace.value.settings)); dirty.value = false; message.value = '已撤销未保存的设置' }
onBeforeRouteLeave(() => { if (dirty.value) { message.value = '请先保存或撤销设置'; return false } })
useSeoMeta({ title: '设置 — XIAOJUESHI' })
</script>
<template><AdminShell><main class="workspace-page settings-page"><div class="workspace-page-heading"><div><div class="page-eyebrow">SETTINGS</div><h1>设置</h1><p>管理站点信息、外观、编辑偏好与数据。</p></div></div><div class="settings-tabs" role="tablist" aria-label="站点设置"><button v-for="option in [{ id: 'general', name: '基本信息', icon: Settings2 }, { id: 'appearance', name: '外观', icon: Sun }, { id: 'editor', name: '编辑与发布', icon: PenLine }, { id: 'data', name: '数据管理', icon: Database }]" :key="option.id" role="tab" :aria-selected="tab === option.id" :class="{ active: tab === option.id }" @click="changeTab(option.id)"><component :is="option.icon" :size="15" />{{ option.name }}</button></div><p v-if="message" class="notice" role="status">{{ message }}</p>
<form v-if="form && tab !== 'data'" class="settings-form" @submit.prevent="save" @input="dirty = true" @change="dirty = true">
<section v-if="tab === 'general'" class="workspace-panel"><div class="panel-heading"><h2>基本信息</h2><span class="small-pill">公开站点</span></div><p>这些信息用于导航、页面标题和搜索摘要。</p><label class="form-field">站点名称<input v-model="form.name" required maxlength="80" /></label><label class="form-field">站点简介<textarea v-model="form.description" rows="3" maxlength="500" /></label><label class="form-field">SEO 默认标题<input v-model="form.seoTitle" required maxlength="150" /></label><label class="form-field">GitHub 链接<input v-model="form.github" type="url" placeholder="https://github.com/…" maxlength="300" /></label></section>
<section v-if="tab === 'appearance'" class="workspace-panel"><div class="panel-heading"><h2>默认外观</h2></div><p>前台与后台共用主题。访客主动选择的主题优先于站点默认值。</p><div class="theme-options" role="group" aria-label="站点默认主题"><button v-for="choice in choices" :key="choice.id" type="button" :aria-pressed="form.theme === choice.id" class="theme-option" :class="{ selected: form.theme === choice.id }" @click="form.theme = choice.id; dirty = true"><div class="theme-sample" :class="`sample-${choice.id}`"><span /><i /><i /><i /></div><div><component :is="choice.icon" :size="16" /><strong>{{ choice.name }}</strong><Check v-if="form.theme === choice.id" :size="15" /></div><small>{{ choice.caption }}</small></button></div><div class="personal-theme"><h3>当前设备</h3><p>当前选择：{{ choices.find(c => c.id === selection)?.name }}。可以即时预览，不需要保存站点设置。</p><div class="segmented"><button v-for="choice in choices" :key="choice.id" type="button" :class="{ active: selection === choice.id }" @click="setTheme(choice.id)">{{ choice.name }}</button></div><button type="button" class="subtle-button" @click="resetTheme">清除设备偏好，使用站点默认值</button></div></section>
<section v-if="tab === 'editor'" class="workspace-panel"><div class="panel-heading"><h2>编辑与发布</h2></div><p>保存编辑稿不会自动公开内容；新内容始终默认私密。</p><label class="form-field">默认内容类型<select v-model="form.defaultKind"><option v-for="type in types" :key="type.id" :value="type.id">{{ type.name }}</option></select></label><label class="form-field">自动保存间隔（秒）<input v-model.number="form.autosaveSeconds" type="number" min="1" max="30" required /><small>支持 1–30 秒，编辑器会显示实际保存状态。</small></label><label class="settings-check"><input v-model="form.showReadingTime" type="checkbox" /><span><strong>显示阅读时长</strong><small>在公开文章列表与阅读页显示预计阅读时间。</small></span></label><label class="settings-check"><input v-model="form.codeWrap" type="checkbox" /><span><strong>代码块自动换行</strong><small>关闭时，长代码在代码块内横向滚动。</small></span></label></section>
<div class="settings-save-bar"><span>{{ dirty ? '有未保存的设置' : '设置已同步' }}</span><button v-if="dirty" type="button" class="button button-outline" @click="discard">撤销更改</button><button class="button button-dark" :disabled="busy || !dirty"><Check :size="15" />{{ busy ? '正在保存…' : '保存设置' }}</button></div></form>
<div v-if="tab === 'data'" class="data-management"><div class="data-summary"><div v-for="metric in [{ name: '内容', value: dataInfo?.content }, { name: '知识库', value: dataInfo?.bases }, { name: '分类与标签', value: (dataInfo?.terms || 3) - 3 }, { name: '附件', value: dataInfo?.assets }]" :key="metric.name"><span>{{ metric.name }}</span><strong>{{ metric.value || 0 }}</strong></div></div><section class="workspace-panel"><div class="panel-heading"><h2>导出与备份</h2><Download :size="18" /></div><p>包含全部正文、编辑稿、发布版本、历史版本、目录、分类、标签、类型与站点设置。不包含管理员密码和会话。</p><div class="export-options"><a href="/api/admin/backup?format=zip" class="export-option"><div><h3>完整 ZIP</h3><p>Markdown 文件、JSON 元数据、原始图片与恢复清单，方便迁移。</p></div><Download :size="18" /></a><a href="/api/admin/backup" class="export-option"><div><h3>JSON 恢复包</h3><p>单个完整文件，适合备份和恢复到另一实例。</p></div><Download :size="18" /></a></div></section><section class="workspace-panel"><div class="panel-heading"><h2>导入与恢复</h2><Upload :size="18" /></div><p>支持多篇 Markdown，或单个本站 JSON / ZIP 备份，单次最多 100MB。先检查结果，再确认执行；现有内容不会被覆盖。</p><input ref="fileInput" class="import-file-input" type="file" accept=".md,.json,.zip" multiple aria-label="选择导入文件" @change="fileChanged" /><p v-if="files.length" class="file-selection">已选择 {{ files.length }} 个文件：{{ files.map(f => f.name).join('、') }}</p><label class="settings-check"><input v-model="restoreSettings" type="checkbox" /><span><strong>同时恢复备份中的站点设置</strong><small>默认保留当前站点名称、主题及编辑偏好。</small></span></label><button class="button button-outline" :disabled="importing || !files.length" @click="runImport('plan')"><Upload :size="15" />{{ importing ? '正在处理…' : '预览导入结果' }}</button><div v-if="plan" class="import-plan" role="region" aria-label="导入预览"><h3>确认导入计划</h3><div class="import-plan-stats"><span>新增内容 <strong>{{ plan.add }}</strong></span><span>跳过内容 <strong>{{ plan.skip }}</strong></span><span>新增知识库 <strong>{{ plan.knowledge }}</strong></span><span>新增组织项 <strong>{{ plan.terms }}</strong></span><span>待检查附件 <strong>{{ plan.assets }}</strong></span></div><p v-if="plan.conflicts.length">以下内容链接冲突，将跳过：{{ plan.conflicts.join('、') }}</p><p>{{ plan.restoreSettings ? '将同时恢复站点设置。' : '保留本站现有设置。' }}执行过程中任一写入失败，将回滚本次导入。</p><div class="panel-actions"><button class="button button-outline" :disabled="importing" @click="plan = null">取消</button><button class="button button-dark" :disabled="importing" @click="runImport('apply')">{{ importing ? '正在导入…' : '确认执行导入' }}<ArrowUpRight :size="15" /></button></div></div></section><section class="workspace-panel"><div class="panel-heading"><h2>操作记录</h2><button class="icon-button" aria-label="刷新数据记录" @click="refreshData()"><RefreshCw :size="17" /></button></div><p v-if="!dataInfo?.operations.length">暂无导入导出记录。</p><div v-for="(operation, index) in dataInfo?.operations" :key="index" class="operation-row"><span class="operation-dot" :class="{ failed: !operation.success }" /><div><strong>{{ operation.action }}</strong><p>{{ operation.detail }}</p></div><time>{{ operation.at.slice(0,16).replace('T',' ') }} UTC</time></div></section></div></main></AdminShell></template>
